def new_tracking_number(when):
    # Salinan sengaja: migrasi tidak boleh bergantung pada kode model yang bisa berubah.
    suffix = "".join(secrets.choice(_ALPHABET) for _ in range(6))
    return f"PS-{when:%y%m%d}-{suffix}"


